const tabId = 1962625065;

const allCourses = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('main ul li'));
  return cards.map(card => {
    const titleEl = card.querySelector('h3');
    if (!titleEl) return null;
    const title = titleEl.textContent.trim();

    // Partner
    const partnerEl = card.querySelector('p[class*="cds-ProductCard-partnerNames"]') || card.querySelector('span[class*="partner-name"]');
    let partner = partnerEl ? partnerEl.textContent.trim() : '';

    // Link
    const linkEl = card.querySelector('a');
    const url = linkEl ? linkEl.href : '';

    // Full card text items
    const lines = card.innerText.split('\n').map(l => l.trim()).filter(Boolean);

    // Let's parse metadata from lines
    let skills = '';
    let rating = '';
    let reviews = '';
    let level = '';
    let type = '';
    let duration = '';
    let status = '';

    for (const line of lines) {
      if (line.startsWith("Skills you'll gain:")) {
        skills = line.replace("Skills you'll gain:", "").trim();
      } else if (line.includes('★') || line.includes('stars')) {
        // e.g. "4.9 stars, 33K reviews, Beginner, Course, 1 - 3 Months" or "★ 4.9 (33K) · Beginner · Course · 1 - 3 Months"
        const match = line.match(/([0-9\.]+)\s*(?:stars|★)?\s*\(?([0-9\.]+[kK]?\s*reviews|[0-9\.]+[kK]?)\)?/);
        if (match && !rating) {
          rating = match[1];
          reviews = match[2];
        }
        if (line.includes('Beginner')) level = 'Beginner';
        else if (line.includes('Intermediate')) level = 'Intermediate';
        else if (line.includes('Advanced')) level = 'Advanced';
        else if (line.includes('Mixed')) level = 'Mixed';

        if (line.includes('Course')) type = 'Course';
        else if (line.includes('Specialization')) type = 'Specialization';
        else if (line.includes('Professional Certificate')) type = 'Professional Certificate';

        const durMatch = line.match(/(\d+\s*-\s*\d+\s*(?:Months|Weeks|Days)|\d+\s*(?:Months|Weeks|Hours|Days))/i);
        if (durMatch && !duration) duration = durMatch[1];
      } else if (line.startsWith('Status:')) {
        status = line.replace('Status:', '').trim();
      }
    }

    // If partner is not set, the first line is usually the partner
    if (!partner && lines.length > 0 && lines[0] !== title) {
      partner = lines[0];
    }

    return {
      title,
      partner,
      type: type || (url.includes('/specializations/') ? 'Specialization' : 'Course'),
      rating,
      reviews,
      level,
      duration,
      skills,
      status,
      url,
      lines
    };
  }).filter(Boolean);
});

